def words(s):
    return [w for line in s.splitlines() if not re.fullmatch(r'\s*(?:`{3,}|~{3,})\w*\s*',line) for w in line.split() if not re.fullmatch(r'[`~*_\-#|>]+',w)]
def longest(s):
    return max((len(m.group()) for m in re.finditer(r'`+',s)),default=0)
def quote(s):
    return '**"'+''.join('\\'+c if c in string.punctuation else c for c in s)+'"**'
def block(s):
    marker='`'*max(3,longest(s)+1)
    return marker+'text\n'+s+'\n'+marker
def edited(i,replacements=None,rewrite=None,why=None):
    source=sources[i]
    if rewrite is not None:
        result=rewrite
        changes=[(source,result,why)]
    else:
        result=source
        changes=[]
        for old,new,explanation in replacements:
            assert old in result
            result=result.replace(old,new,1)
            changes.append((old,new,explanation))
    response=block(result)+'\n\nChanges:\n'+'\n'.join('- '+quote(old)+' → '+quote(new)+': '+explanation for old,new,explanation in changes)
    return {'response':response,'text':result,'changes':changes}
