def inline(s):
    out=[]; pos=0
    pattern=r'\*\*"((?:\\.|[^"\\])*)"\*\*'
    for match in re.finditer(pattern,s):
        out.append(html.escape(s[pos:match.start()]))
        literal=re.sub(r'\\([\x21-\x2f\x3a-\x40\x5b-\x60\x7b-\x7e])',r'\1',match.group(1))
        out.append('<strong>&quot;'+html.escape(literal)+'&quot;</strong>')
        pos=match.end()
    out.append(html.escape(s[pos:]))
    return ''.join(out)
def render(s):
    result=[]; lines=s.splitlines(); j=0
    while j<len(lines):
        m=re.fullmatch(r'(`{3,})text',lines[j])
        if m:
            marker=m.group(1); j+=1; body=[]
            while j<len(lines) and lines[j]!=marker:
                body.append(lines[j]); j+=1
            assert j<len(lines)
            result.append('<pre><code class="language-text">'+html.escape('\n'.join(body))+'</code></pre>')
        elif lines[j].startswith('- '):
            result.append('<ul><li>'+inline(lines[j][2:])+'</li></ul>')
        elif lines[j]:
            result.append('<p>'+inline(lines[j])+'</p>')
        j+=1
    return '\n'.join(result)
